export const canonical48WorkDatabaseBytes = (): Buffer => {
  const recipe = readFileSync(new URL("./canonical48-work-generator.original.ts.txt", import.meta.url));
  if (createHash("sha256").update(recipe).digest("hex") !== canonical48WorkFixture.generatorSha256) {
    throw new Error("Canonical48 Work generator integrity mismatch.");
  }
  const bytes = gunzipSync(Buffer.from(image, "base64"), { maxOutputLength: canonical48WorkFixture.databaseBytes });
  if (bytes.length !== canonical48WorkFixture.databaseBytes
    || createHash("sha256").update(bytes).digest("hex") !== canonical48WorkFixture.databaseSha256) {
    throw new Error("Canonical48 Work database integrity mismatch.");
  }
  return bytes;
};
